    // Calculate midpoint
    double c = (a + b) * 0.5;
    double fa = f(a);
    double fb = f(b);
    double fc = f(c);

    // Simpson's rule for the whole interval [a,b]
    double h = b - a;
    double simpson_full = h / 6.0 * (fa + 4.0 * fc + fb);

    // Simpson's rule for the two subintervals [a,c] and [c,b]
    double fa_c = f((a + c) * 0.5);
    double fc_b = f((c + b) * 0.5);
    double h_half = h * 0.5;
    double simpson_left = h_half / 6.0 * (fa + 4.0 * fa_c + fc);
    double simpson_right = h_half / 6.0 * (fc + 4.0 * fc_b + fb);
    double simpson_half = simpson_left + simpson_right;

    // Error estimation: |S(a,b) - S(a,c) - S(c,b)| < 15 * precision
    // The factor 15 comes from the error term in Simpson's rule
    if (std::abs(simpson_full - simpson_half) <= 15.0 * precision) {
        return simpson_half;
    } else {
        // Recursively apply adaptive Simpson to each subinterval
        return adaptive_simpson(f, a, c, precision * 0.5) + 
               adaptive_simpson(f, c, b, precision * 0.5);
    }

